import Link from "next/link";

/**
 * The Relay mark and wordmark, generated by scripts/brand.ts (brand/README.md). The tile is the
 * flat mark — nested objects go flat so shadows never stack (frontend.md §6).
 */
export function Logo({ href = "/" }: { href?: string }) {
  return (
    <Link href={href} className="flex min-h-11 items-center gap-2.5" aria-label="Relay home">
      {/* eslint-disable-next-line @next/next/no-img-element -- static SVG, no optimisation to gain */}
      <img src="/brand/relay-mark.svg" alt="" width={36} height={36} className="h-9 w-9 shrink-0" />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src="/brand/relay-wordmark.svg" alt="" width={61} height={26} className="h-[26px] w-auto translate-y-[4px]" />
    </Link>
  );
}
